begin;
alter table public.products
  add column source_key text,
  add column category text not null default 'Menú',
  add column sort_order integer not null default 0,
  add column option_groups jsonb not null default '[]'::jsonb check (jsonb_typeof(option_groups)='array'),
  add column source_url text;
create unique index products_business_source on public.products(business_id,source_key);
alter table public.businesses add column map_url text;
alter table public.order_items add column selections jsonb not null default '[]'::jsonb check (jsonb_typeof(selections)='array');
alter table public.orders add column request_payload jsonb;

